<?php require '../includes/core.php';$u=require_subscriber();if($u['role']==='admin')go('admin/tickets.php');$s=db()->prepare('SELECT * FROM tickets WHERE user_id=? ORDER BY created_at DESC');$s->execute([$u['id']]);layout_start('Chamados',$u);?><div class="actions" style="justify-content:space-between"><h1>Meus chamados</h1><a class="btn" href="new-ticket.php">+ Novo chamado</a></div><div class="card table-wrap"><table class="table"><thead><tr><th>Nº</th><th>Assunto</th><th>Categoria</th><th>Status</th><th>Data</th><th></th></tr></thead><tbody><?php foreach($s as $t):?><tr><td>#<?=$t['id']?></td><td><?=h($t['subject'])?></td><td><?=h($t['category'])?></td><td><?=status_badge($t['status'])?></td><td><?=date('d/m/Y',strtotime($t['created_at']))?></td><td><a href="ticket.php?id=<?=$t['id']?>">Abrir</a></td></tr><?php endforeach;?></tbody></table></div><?php layout_end();?>